import {createPriceLoader} from './price-loader.js';
import {companies,events,groups} from './catalog.js';
import {parameters,calibrate,simulate,quantile,crps,blackScholes,parseCSV} from './model.js';
import {marketThemes,sectors,mathTopics} from './content.js';
import {rankedForecasts,stockSummaries,factorChecks} from './leaderboard.js';
import {sizePosition,longTermProjection} from './sizing.js';
import {portfolioPage} from './portfolio-page.js';
const $=s=>document.querySelector(s),view=$('#view');
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=(n,d=1)=>(n*100).toFixed(d)+'%',num=(n,d=1)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=(n,d=2)=>(n<0?'−$':'$')+num(Math.abs(n),d);
const tip=(message)=>`<span class="info-tip" tabindex="0" aria-label="Explanation: ${esc(message)}">ⓘ<span class="info-pop" role="tooltip">${esc(message)}</span></span>`;
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Browser storage is full or unavailable. Download your forecast to keep it.');return false}};
let archive,config={configured:false},imports=read('quantlab-imports',{}),journal=read('quantlab-journal',[]),active='game';
if(!Array.isArray(journal))journal=[];
let state={symbol:'AAPL',mode:'forward',days:21,date:'2015-08-03',weights:Object.fromEntries(events.map(e=>[e.id,50])),allocation:50,investment:500,budget:1000,maxLossPct:10,riskProfile:'balanced',holdYears:5,inflation:2.5,shock:{probability:0,move:0},locked:null,revealed:false},model,baseline,context,params;
const draft=read('quantlab-game-draft',null);
if(draft&&companies.some(c=>c.symbol===draft.symbol)&&['forward','replay'].includes(draft.mode)&&[21,63,126,252,504,1260].includes(draft.days)&&draft.weights&&events.every(e=>Number.isFinite(draft.weights[e.id])&&draft.weights[e.id]>=0&&draft.weights[e.id]<=100)){
 Object.assign(state,{symbol:draft.symbol,mode:draft.mode,days:draft.days,weights:draft.weights});
 if(typeof draft.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(draft.date)&&draft.date<=new Date().toISOString().slice(0,10))state.date=draft.date;
 if(draft.shock&&Number.isFinite(draft.shock.probability)&&draft.shock.probability>=0&&draft.shock.probability<=1&&Number.isFinite(draft.shock.move)&&draft.shock.move>=-.8&&draft.shock.move<=1)state.shock=draft.shock;
 for(const key of ['investment','budget','allocation','maxLossPct','inflation','holdYears'])if(Number.isFinite(draft[key]))state[key]=draft[key];
}
function saveDraft(){save('quantlab-game-draft',{symbol:state.symbol,mode:state.mode,days:state.days,date:state.date,weights:state.weights,shock:state.shock,investment:state.investment,budget:state.budget,allocation:state.allocation,maxLossPct:state.maxLossPct,inflation:state.inflation,holdYears:state.holdYears})}
let liveCache={},loading=false,renderTimer;
let scenarioSlots=read('quantlab-scenarios',{});
const priceLoader=createPriceLoader(),autoRequested=new Map();let requestRevision=0,replayDateExplicit=Boolean(draft?.date&&state.mode==='replay'),pendingPriceKey=null;
let priceProvider=read('quantlab-price-provider','yahoo');if(!['yahoo','alpha'].includes(priceProvider))priceProvider='yahoo';
const providerNames={yahoo:'Yahoo Finance',alpha:'Alpha Vantage'};let providerStatus={yahoo:{state:'untested',message:'Public endpoint available to test; connection not verified.'},alpha:{state:'untested',message:'Requires a configured server-side key.'}};
function providerAvailable(){return priceProvider==='yahoo'?Boolean(config.providers?.yahoo?.available):Boolean(config.providers?.alpha?.available)}
function replayIsHidden(){return state.mode==='replay'&&!state.revealed}
function statusMarkup(){const data=liveCache[priceProvider+':'+state.symbol],st=providerStatus[priceProvider];
 if(loading)return `<span class="pill">LOADING ${esc(state.symbol)}</span> Getting daily history from ${esc(providerNames[priceProvider])}…`;
 const applies=st.symbol===state.symbol;
 const status=applies?st.state:data?'loaded':'untested';
 const hidden=replayIsHidden(),message=hidden&&status==='loaded'?state.symbol+' history ready. Only observations through the replay origin are shown until reveal.':applies?st.message:data?state.symbol+' history available through '+data.asOf+'.':'Daily history loads automatically when you choose a stock.';
 return `<span class="pill ${status==='error'?'warn':''}">${esc(providerNames[priceProvider])} / ${status==='loaded'?'DATA RECEIVED':status==='error'?'UNAVAILABLE':'AUTO-LOAD'}</span> ${esc(message)}${!hidden&&data?.fetchedAt?' · fetched '+esc(data.fetchedAt.replace('T',' ').slice(0,19))+' UTC':''}`;
}
function latestCloseMarkup(){const data=sourceFor(state.symbol);if(data?.kind!=='provider')return '';const hidden=replayIsHidden(),last=hidden?data.rows.findLast(r=>r.date<=state.date):data.rows.at(-1);if(!last)return '';const price=last.rawClose??last.close;return `<div class="latest-close"><span>${esc(state.symbol)} / ${hidden?'CLOSE AT REPLAY ORIGIN':'LATEST COMPLETED DAILY CLOSE'}</span><strong>${data.currency==='USD'?'$':''}${num(price,2)}</strong><small>${esc(last.date)} · ${esc(data.currency||'')} · ${last.rawClose?'unadjusted close':'source close'}<br>${hidden?'Later prices are hidden until the outcome is revealed.':'Daily history; today’s unfinished session is excluded.'}</small></div>`;}
function replayOriginFromData(){if(state.mode!=='replay'||replayDateExplicit)return;const rows=sourceFor(state.symbol)?.rows;if(rows?.length>state.days+40)state.date=rows[rows.length-state.days-1].date;}
function cancelPriceLoad(){if(loading&&pendingPriceKey)autoRequested.delete(pendingPriceKey);priceLoader.cancel();requestRevision++;loading=false;pendingPriceKey=null;}
function ensurePrices(){if(state.locked||imports[state.symbol]||!providerAvailable())return;
 const origin=state.mode==='replay'&&replayDateExplicit?state.date:null,key=[priceProvider,state.symbol,origin||'recent',state.days].join(':');
 if(Date.now()-(autoRequested.get(key)||0)<15*60*1000)return;
 autoRequested.set(key,Date.now());refreshData({auto:true,origin});
}
function paintLoading(){if(active!=='game')return;if($('#feedStatus'))$('#feedStatus').innerHTML=statusMarkup();if($('#refresh')){$('#refresh').disabled=loading||Boolean(state.locked);$('#refresh').textContent=loading?'Loading daily history…':'↻ Refresh prices'}if($('#lock'))$('#lock').disabled=loading||Boolean(state.locked);if($('#chart'))$('#chart').setAttribute('aria-busy',String(loading));}

function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(renderTimer);renderTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function company(){return companies.find(x=>x.symbol===state.symbol)}
function sourceFor(symbol){return imports[symbol]||liveCache[priceProvider+':'+symbol]||(archive?.series[symbol]?{rows:archive.series[symbol],label:'Plotly historical archive',source:archive.url,kind:'archive',adjustment:'Archived series; adjustment method unverified'}:null)}
function establish(){const c=company(),data=sourceFor(c.symbol);let rows=data?.rows||[];let index=rows.length-1;if(state.mode==='replay')index=rows.findLastIndex(r=>r.date<=state.date);const enough=index>=40,observed=enough?rows.slice(Math.max(0,index-252),index+1):[];baseline=enough?calibrate(observed):{mu:c.mu,sigma:c.sigma,observations:0};const start=enough?rows[index].date:null,startPrice=enough?(rows[index].rawClose??rows[index].close):100;const actual=enough&&state.mode==='replay'?rows.slice(index,index+state.days+1):[];context={data,rows,index,start,startPrice,priceMode:enough?'dollars':'index',enough,actual,observed,hasActual:actual.length===state.days+1,stale:enough&&(Date.now()-Date.parse(start+'T00:00:00Z'))/86400000>7};params=parameters(c,state.weights,baseline);model=simulate({s0:startPrice,mu:params.mu,sigma:params.sigma,days:state.days,shock:state.shock});}
function heading(k,title,sub,right=''){return `<div class="page-heading"><div><div class="eyebrow"><span class="dot"></span>${k}</div><h1>${title}</h1><p>${sub}</p></div>${right?`<div class="edition">${right}</div>`:''}</div>`}
function visibleSourceLabel(data){return replayIsHidden()&&data?.kind==='provider'?providerNames[priceProvider]+' daily · replay snapshot':data?.label||'Illustrative inputs'}
function sourceLine(){let c=context;if(!c.enough)return `<span class="pill warn">ILLUSTRATIVE INPUTS</span><span>No usable price history for this company. Import CSV or connect a provider. Replay scoring is unavailable.</span>`;return `<span class="pill ${c.data.kind==='archive'?'warn':''}">${c.data.kind==='archive'?'HISTORICAL ARCHIVE':c.data.kind==='import'?'YOUR CSV':'PROVIDER DATA'}</span><span>Origin ${c.start} · starting close ${money(c.startPrice)} · ${baseline.observations} pre-origin returns · ${esc(visibleSourceLabel(c.data))}</span>${state.mode==='forward'&&c.stale?'<span class="pill warn">STALE / ARCHIVED ORIGIN</span>':''}<span>${c.data.currency?esc(c.data.currency)+' · ':''}${esc(c.data.adjustment||'CSV adjustment basis: user supplied')}</span>`}
function choices(){return companies.map(c=>`<option value="${c.symbol}" ${state.symbol===c.symbol?'selected':''}>${c.symbol} — ${c.name}</option>`).join('')}
function game(){establish();view.innerHTML=heading('SIMULATION GAME','Shape a <em>forecast.</em>','Choose a stock and move the assumptions while watching the price paths.')+`
<div class="controls-strip"><label class="field">COMPANY<select id="company">${choices()}</select></label><div class="field mode-field"><span class="mode-label">MODE</span><span class="segmented"><button id="replay" class="${state.mode==='replay'?'selected':''}">Historical replay</button><button id="forward" class="${state.mode==='forward'?'selected':''}">Forward lab</button></span></div><label class="field">HORIZON<select id="horizon"><option value="21" ${state.days===21?'selected':''}>1 month · 21 sessions</option><option value="63" ${state.days===63?'selected':''}>3 months · 63 sessions</option><option value="126" ${state.days===126?'selected':''}>6 months · 126 sessions</option><option value="252" ${state.days===252?'selected':''}>1 year · 252 sessions</option><option value="504" ${state.days===504?'selected':''}>2 years · 504 sessions</option><option value="1260" ${state.days===1260?'selected':''}>5 years · 1,260 sessions</option></select></label><button class="secondary" id="refresh">↻ Refresh prices</button></div>
<div class="filter-row">${state.mode==='replay'?`<label class="field">REPLAY START DATE<input id="origin" type="date" value="${state.date}" max="${new Date().toISOString().slice(0,10)}"></label><span class="small-text">Prices after the origin stay hidden until you reveal the outcome.</span>`:`<span class="small-text">Forecast from the latest available observation. Older data stays labeled as an archived exercise.</span>`}</div>
${latestCloseMarkup()}${state.days>=504?'<div class="callout amber">Two- and five-year paths hold today’s estimated drift, volatility, and event weights fixed. Yahoo history informs calibration but cannot supply future inflation or news; these long-horizon outcomes are especially speculative.</div>':''}<details class="source-details"><summary>Price source and adjustments</summary><div class="source-bar">${sourceLine()} <a href="#data">Data settings</a></div></details><div id="feedStatus" class="callout ${providerStatus[priceProvider].state==='error'?'amber':''}" style="margin-bottom:18px;font-size:10px">${statusMarkup()}</div>
<div class="play-workspace"><aside class="panel assumptions" id="assumptions"><div class="panel-head"><h3>02 / Shape your assumptions</h3><button class="quiet" id="reset">Reset ↺</button></div><div class="assumptions-intro"><p><b>50% = baseline.</b> Move left to weaken an effect, right to strengthen it. These are impact adjustments, not event probabilities. ${tip('The coefficients linking sliders to expected return and volatility are illustrative teaching values. They have not been estimated from dated event studies or validated as causal effects on this stock.')}</p></div>${groups.map((g,i)=>`<details class="slider-group" ${i===0?'open':''}><summary>${g}<span>${events.filter(e=>e.group===g).length} FACTORS</span></summary>${events.filter(e=>e.group===g).map(e=>`<div class="slider-item"><label for="${e.id}">${e.name} ${tip(e.description)}<output id="out-${e.id}">${state.weights[e.id]}%</output></label><input type="range" id="${e.id}" data-event="${e.id}" min="0" max="100" value="${state.weights[e.id]}" aria-label="${e.name}"><div class="slider-ends"><span>WEAKER</span><span>BASELINE</span><span>STRONGER</span></div></div>`).join('')}</details>`).join('')}<div class="assumption-bottom"><div class="parameter-chips" id="paramChips"></div></div></aside>
<div class="lab-grid"><div class="left-col"><section class="shock-controls panel"><div class="panel-body"><h3>Event shock ${tip('A separate one-time price jump. Each simulated path has your chosen chance of experiencing the move at a random session during this horizon. This is a hypothetical scenario, not a measured event probability.')}</h3><div class="shock-fields"><label class="field">CHANCE / %<input id="shockProbability" type="number" min="0" max="100" step="5" value="${state.shock.probability*100}"></label><label class="field">PRICE MOVE / %<input id="shockMove" type="number" min="-80" max="100" step="1" value="${state.shock.move*100}"></label></div></div></section><section class="panel chart-panel" id="paths"><div class="panel-head"><h3>${esc(company().name)} <span class="small-text">/ ${state.symbol}</span></h3><span class="pill">03 / PRICE SCENARIOS · GBM</span></div><div class="chart-title"><div class="quote" id="headline">${context.enough?money(model.median):num(model.median)}<small>PROJECTED MEDIAN / ${context.enough?'SHARE PRICE':'ILLUSTRATIVE INDEX'} ${tip('The middle ending value of the simulation. It is a dollar share price when dated history exists. A rising modeled median is conditional on your assumptions, not a claim that the market will rise.')}</small></div><div class="legend"><span><i></i>Current median ${tip('The green line is the middle simulated price at each date under your assumptions. An upward slope is a conditional model result, not evidence that the stock is likely to rise in the real market.')}</span><span><i class="band"></i>Middle 80% ${tip('At each date, about 80% of simulated prices sit inside the shaded band; about 10% are below and 10% above. This is a percentile band, not a promise that an entire path stays inside it.')}</span><span><i class="actual"></i>Actual after reveal</span><span>⋯ Baseline median</span></div></div><div class="chart-wrap" id="chart" aria-label="Simulated price paths and pointwise 80 percent uncertainty band"></div><div class="chart-caption"><span>${context.enough?`START = ${money(context.startPrice)} PER SHARE · ${context.start}`:'START = 100 · ILLUSTRATIVE INDEX'}</span><span id="chartEnd">SESSION ${state.days}</span></div><div class="chart-footer"><span><strong>1,200</strong> paths</span><span><strong>Fixed seed</strong> for fair comparisons</span><span>The middle 80% keeps the graph readable; 10% of modeled values lie on each side.</span></div></section>
<div class="metric-grid" id="metrics"></div><details class="model-details"><summary>Explore distribution and parameter details</summary><div class="lower-grid"><section class="panel"><div class="panel-head"><h3>Where simulated prices end ${tip('Each bar counts how many simulated paths finish in a price range at the selected horizon. It shows the distribution of possible endings under the model, not actual future probabilities.')}</h3><span class="eyebrow">ENDING PRICES</span></div><div class="panel-body"><svg class="histogram" id="histogram" role="img" aria-label="Histogram of simulated terminal prices"></svg><div class="small-text" id="modalBin"></div></div></section><section class="panel"><div class="panel-head"><h3>What your view changes</h3></div><div class="panel-body" id="implications"></div></section></div></details>
<section class="panel" id="scenarioPanel"><div class="panel-body"><div class="panel-head"><h3>Compare scenarios</h3><div class="buttons"><button class="secondary" id="saveBull">Save as bull</button><button class="secondary" id="saveBear">Save as bear</button></div></div><div id="scenarioComparison"></div></div></section><div class="game-actions"><button class="primary lime" id="lock">Lock forecast</button><button class="secondary" id="reveal">Reveal actual outcome</button><button class="secondary hidden" id="journalShortcut">Open forecast journal</button><a class="secondary" href="#calculator">Continue to stock calculator</a></div><p class="notice" id="lockNotice">${state.mode==='replay'?'Lock before revealing later prices.':'A locked forecast is saved in this browser for later evaluation.'}</p><div id="results" class="results"></div></div>
</div>
</div>`;
$('#company').onchange=e=>{cancelPriceLoad();state.symbol=e.target.value;replayDateExplicit=false;newRound();replayOriginFromData();game()};$('#horizon').onchange=e=>{state.days=Number(e.target.value);newRound();replayOriginFromData();game()};$('#replay').onclick=()=>{state.mode='replay';newRound();replayOriginFromData();game()};$('#forward').onclick=()=>{state.mode='forward';replayDateExplicit=false;newRound();game()};if($('#origin'))$('#origin').onchange=e=>{if(e.target.value){state.date=e.target.value;replayDateExplicit=true;newRound();game()}};$('#refresh').onclick=()=>refreshData({force:true,origin:state.mode==='replay'&&replayDateExplicit?state.date:null});$('#reset').onclick=()=>{newRound();state.weights=Object.fromEntries(events.map(e=>[e.id,50]));state.shock={probability:0,move:0};game()};document.querySelectorAll('[data-event]').forEach(el=>el.oninput=e=>{state.weights[el.id]=Number(el.value);$('#out-'+el.id).value=el.value+'%';updateSimulation()});for(const id of ['shockProbability','shockMove'])$('#'+id).onchange=e=>{const value=Number(e.target.value);if(!e.target.checkValidity()||!Number.isFinite(value))return;state.shock[id==='shockProbability'?'probability':'move']=value/100;updateSimulation()};$('#saveBull').onclick=()=>saveScenario('bull');$('#saveBear').onclick=()=>saveScenario('bear');$('#journalShortcut').onclick=showJournal;$('#lock').onclick=lockForecast;$('#reveal').onclick=reveal;$('#reveal').disabled=!state.locked;updateSimulation();if(state.locked){applyLocked();if(state.revealed)reveal();}paintLoading();queueMicrotask(ensurePrices);}
function newRound(){state.locked=null;state.revealed=false;}
function displayPrice(value,d=2){return context.enough?money(value,d):num(value,d)}
function updateSimulation(){
 params=parameters(company(),state.weights,baseline);
 model=simulate({s0:context.startPrice,mu:params.mu,sigma:params.sigma,days:state.days,shock:state.shock});
 saveDraft();
 $('#headline').innerHTML=`${displayPrice(model.median)}<small>PROJECTED MEDIAN / ${context.enough?'SHARE PRICE':'ILLUSTRATIVE INDEX'} ${tip('The middle ending value of the simulation. It is a dollar share price when dated history exists. A rising modeled median is conditional on your assumptions, not a claim that the market will rise.')}</small>`;
 const from=context.startPrice,returnText=v=>pct(v/from-1,0);
 const metrics=[
  ['MEDIAN RETURN',pct(model.median/from-1),`Middle simulated ending: ${displayPrice(model.median)}`,`The middle ending return across 1,200 simulated paths. Half end below it and half above. This is conditional on your sliders, not a guaranteed gain.`],
  ['CHANCE OF LOSS',pct(model.loss,0),`Ending below ${displayPrice(from)}`,`The share ends below its starting close in this fraction of simulated paths. It is a model frequency, not a measured real-world probability.`],
  ['80% ENDING INTERVAL',`${displayPrice(model.lo,0)}–${displayPrice(model.hi,0)}`,`${returnText(model.lo)} to ${returnText(model.hi)}`,`The middle 80% of simulated ending prices are between ${displayPrice(model.lo)} and ${displayPrice(model.hi)} (${returnText(model.lo)} to ${returnText(model.hi)} from the start). About 10% end below and 10% above. We show percentiles rather than standard deviations because prices are asymmetric under this model. This is not a guarantee.`],
  ['5TH PERCENTILE',displayPrice(model.p05),`${returnText(model.p05)} from the starting close`,`A downside marker: about 5% of simulated endings fall below ${displayPrice(model.p05)} (${returnText(model.p05)} from the start). Still worse outcomes are possible.`]
 ];
 $('#metrics').innerHTML=metrics.map(([label,value,note,help])=>`<div class="metric"><small>${label} ${tip(help)}</small><b>${value}</b><span>${note}</span></div>`).join('');
 $('#paramChips').innerHTML=`<span>μ ${pct(params.mu)}</span><span>σ ${pct(params.sigma)}</span><span>Δμ ${pct(params.mu-baseline.mu)}</span>`;
 drawChart();drawHistogram();renderScenarioComparison();
 const changed=params.effects.filter(e=>e.x!==0).sort((a,b)=>Math.abs(b.drift)+Math.abs(b.vol)-Math.abs(a.drift)-Math.abs(a.vol));
 $('#implications').innerHTML=`<div class="eyebrow">ASSUMPTIONS → ECONOMICS → PARAMETERS</div><p class="small-text">${changed.length?`Your strongest active adjustment is <strong>${esc(changed[0].name.toLowerCase())}</strong>. ${esc(changed[0].description)}`:'You’re using the baseline. Explore a factor to see how your view moves expected returns and dispersion.'}</p><div class="result-row"><span>Expected return rate μ ${tip('Mu is the annualized drift of the stock-price model. It enters dS = μS dt + σS dW. The one-year mean price return is approximately exp(μ) minus 1, while the green median path uses μ minus half of σ squared, so the two can differ. It is an assumption, not a forecast fact.')}</span><b>${pct(baseline.mu)} → ${pct(params.mu)}</b></div><div class="result-row"><span>Annualized volatility σ ${tip('Sigma is the annualized spread of modeled log returns. It multiplies the Brownian shock in dS = μS dt + σS dW; higher sigma widens paths. It is one type of risk and does not capture every real-world danger, such as sudden jumps or permanent business loss. In the separate option sandbox it also changes the hypothetical Black–Scholes price.')}</span><b>${pct(baseline.sigma)} → ${pct(params.sigma)}</b></div><p class="notice">The slider coefficients are illustrative: we have not measured and validated the causal market impact of each event. μ affects the stock forecast; σ affects its spread and the hypothetical option sandbox.</p>`;
 decisionSummary();
}
function pathD(vals,y,x){return vals.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+','+y(v).toFixed(1)).join(' ')}
function realizedPath(rows,startPrice,adjusted){return rows.map(row=>adjusted?startPrice*row.close/rows[0].close:(row.rawClose??row.close))}
function drawChart(){
 const W=720,H=285,p={l:53,r:18,t:14,b:29},actual=state.revealed&&context.hasActual?realizedPath(context.actual,context.startPrice,Boolean(context.data?.adjusted)):null;
 const comparison=simulate({s0:context.startPrice,mu:baseline.mu,sigma:baseline.sigma,days:state.days});
 const all=[...model.bands.map(b=>b.lo),...model.bands.map(b=>b.hi),...comparison.bands.map(b=>b.lo),...comparison.bands.map(b=>b.hi),...(actual||[])],min=Math.min(...all)*.97,max=Math.max(...all)*1.03;
 const y=v=>p.t+(max-v)/(max-min)*(H-p.t-p.b),x=i=>p.l+i/state.days*(W-p.l-p.r);
 const grid=Array.from({length:5},(_,i)=>{let val=min+(max-min)*i/4;return `<line x1="${p.l}" y1="${y(val)}" x2="${W-p.r}" y2="${y(val)}" stroke="#e5ebdb" stroke-dasharray="3 5"/><text x="${p.l-7}" y="${y(val)+3}" text-anchor="end" fill="#9ca88d" font-size="9" font-family="monospace">${context.enough?'$':''}${num(val,0)}</text>`}).join('');
 const hi=model.bands.map(b=>b.hi),lo=model.bands.map(b=>b.lo),band=pathD(hi,y,x)+' '+lo.map((v,i)=>`L${x(state.days-i).toFixed(1)},${y(lo[state.days-i]).toFixed(1)}`).join(' ')+'Z';
 $('#chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${state.days}-session simulation, median ${displayPrice(model.median)}, 80 percent terminal interval ${displayPrice(model.lo)} to ${displayPrice(model.hi)}"><defs><clipPath id="plotclip"><rect x="${p.l}" y="${p.t}" width="${W-p.l-p.r}" height="${H-p.t-p.b}"/></clipPath><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#c4db8b" stop-opacity=".5"/><stop offset="1" stop-color="#e8f0d7" stop-opacity=".3"/></linearGradient></defs>${grid}<g clip-path="url(#plotclip)"><path d="${band}" fill="url(#chartFill)"/>${model.paths.map(a=>`<path d="${pathD(a,y,x)}" fill="none" stroke="#a6ba83" stroke-width=".7" opacity=".28"/>`).join('')}<line x1="${p.l}" y1="${y(context.startPrice)}" x2="${W-p.r}" y2="${y(context.startPrice)}" stroke="#a8b399" stroke-dasharray="4 5"/><path d="${pathD(comparison.bands.map(b=>b.mid),y,x)}" fill="none" stroke="#788d78" stroke-width="1.6" stroke-dasharray="5 4"/><path d="${pathD(model.bands.map(b=>b.mid),y,x)}" fill="none" stroke="#456b37" stroke-width="2.5"/>${actual?`<path d="${pathD(actual,y,x)}" fill="none" stroke="#c27643" stroke-width="2.5"/>`:''}</g><text x="${p.l}" y="${H-6}" fill="#9ca88d" font-family="monospace" font-size="8">SESSION 0</text><text x="${W-p.r}" y="${H-6}" text-anchor="end" fill="#9ca88d" font-family="monospace" font-size="8">SESSION ${state.days}</text></svg>`;
}
function drawHistogram(){
 const a=model.terminal,lo=a[0],hi=a.at(-1),bins=Array(24).fill(0);a.forEach(v=>bins[Math.min(23,Math.floor((v-lo)/(hi-lo||1)*24))]++);
 const max=Math.max(...bins),idx=bins.indexOf(max),bw=(hi-lo)/24;
 $('#histogram').setAttribute('viewBox','0 0 350 140');
 $('#histogram').innerHTML=bins.map((n,i)=>`<rect x="${15+i*13.3}" y="${115-n/max*95}" width="10.5" height="${n/max*95}" rx="1.5" fill="${i===idx?'#779646':'#d5e3b9'}"/>`).join('')+`<text x="15" y="135" font-size="9" fill="#95a283">${displayPrice(lo,0)}</text><text x="330" y="135" text-anchor="end" font-size="9" fill="#95a283">${displayPrice(hi,0)}</text>`;
 $('#modalBin').innerHTML=`Most populated ending-price interval: <strong>${displayPrice(lo+idx*bw)}–${displayPrice(lo+(idx+1)*bw)}</strong> · ${pct(max/a.length,0)} of paths.<br><span class="notice">Each bar counts simulated ending prices. The tallest bar depends on bin width and is not a uniquely most likely price.</span>`;
}
function positionSizing(){const row=context.enough?context.rows[context.index]:null;return sizePosition({terminal:model.terminal,startPrice:context.startPrice,budget:state.budget,allocation:state.allocation,maxLossPct:state.maxLossPct,riskProfile:state.riskProfile,mu:params.mu,days:state.days,price:row?.rawClose??row?.close??null});}
function scenarioKey(){return [state.symbol,state.mode,state.days,context.start||'illustrative'].join(':')}
function saveScenario(name){if(state.locked)return;const key=scenarioKey();scenarioSlots[key]??={};scenarioSlots[key][name]={weights:{...state.weights},shock:{...state.shock}};save('quantlab-scenarios',scenarioSlots);renderScenarioComparison();toast(`${name==='bull'?'Bull':'Bear'} scenario saved for this stock, date, and horizon.`)}
function renderScenarioComparison(){
 const node=$('#scenarioComparison');if(!node)return;
 const base=simulate({s0:context.startPrice,mu:baseline.mu,sigma:baseline.sigma,days:state.days}),slots=scenarioSlots[scenarioKey()]||{};
 const rows=[['Baseline',base],['Current',model],...['bull','bear'].filter(name=>slots[name]).map(name=>{const scenario=slots[name],p=parameters(company(),scenario.weights,baseline);return[name==='bull'?'Bull':'Bear',simulate({s0:context.startPrice,mu:p.mu,sigma:p.sigma,days:state.days,shock:scenario.shock})]})];
 node.innerHTML=`<div class="scenario-table"><div class="scenario-table-head"><span>VIEW</span><span>MEDIAN</span><span>VS BASELINE</span><span>LOSS</span></div>${rows.map(([name,result])=>`<div class="scenario-table-row"><strong>${name}</strong><span>${displayPrice(result.median)}</span><span>${context.enough?money(result.median-base.median):pct(result.median/context.startPrice-base.median/context.startPrice)}</span><span>${pct(result.loss,0)}</span></div>`).join('')}</div><p class="small-text">All views use the same origin, horizon, and random seed. Saved Bull and Bear settings stay in this browser. Changes in the 80% interval are visible on the graph above.</p>`;
}
function decisionSummary(){
 if(!$('#decisionSummary'))return;
 const fields=['allocation','investment','budget','maxLossPct'].map(id=>$('#'+id));if(fields.some(el=>!el||!el.checkValidity()||el.value==='')){$('#decisionSummary').textContent='Enter a valid proposed investment, budget, loss limit, and allocation to compare choices.';$('#sizingResults').innerHTML='';updateLongTerm();return}
 const s=positionSizing(),low=num(s.range[0]*100,1),high=num(s.range[1]*100,1);
 const under=s.weight<=s.maxWeight+1e-9;
 $('#decisionSummary').innerHTML=`<div class="sizing-head"><span>MODEL SIZING BAND ${tip('The two endpoints come from the base return assumption and a lower-return stress case, subject to your downside budget. It is a sensitivity comparison, not a confidence interval or a guaranteed safe amount.')}</span><strong>${low}–${high}% <small>of practice budget</small></strong></div><p>Under the ${esc(state.riskProfile)} utility setting, the base model prefers ${num(s.modeled*100,1)}%; a lower-drift stress case prefers ${num(s.stress*100,1)}%. The modeled 5th-percentile loss limit caps the position at ${num(s.maxWeight*100,1)}%. ${!under?'<b>Your proposed purchase exceeds that model-based downside limit. You can still explore and lock it.</b>':''}</p>`;
 $('#sizingResults').innerHTML=`<div class="sizing-stats"><div><small>YOUR STOCK AMOUNT</small><b>${money(s.invested)}</b><span>${num(s.weight*100,0)}% of ${money(s.budget)}</span></div><div><small>EXPECTED NET P/L ${tip('The average dollar gain or loss across simulated endings after the illustrative trading cost. A few large gains can pull this mean up.')}</small><b>${money(s.expected)}</b><span>Conditional model mean</span></div><div><small>MEDIAN NET P/L ${tip('The middle simulated dollar gain or loss. Half the modeled outcomes are lower and half are higher.')}</small><b>${money(s.median)}</b><span>Middle simulated outcome</span></div><div><small>5TH-PERCENTILE NET P/L ${tip('A severe simulated downside result: roughly 5% of modeled outcomes are worse. It is not the worst possible loss.')}</small><b>${money(s.fifth)}</b><span>${pct(s.lossProbability,0)} simulated loss outcomes</span></div></div><p class="sizing-range">Central 80% simulated net P/L ${tip('From the 10th to 90th percentile: about 80% of modeled dollar results fall in this range. About 10% are below and 10% above; it is not a maximum range.')}: <b>${money(s.p10)} to ${money(s.p90)}</b>. ${pct(s.lossProbability,0)} of simulated outcomes lose money.</p><p class="sizing-shares">${s.shares===null?'Share count appears when a dated stock close is available.':`At the ${esc(context.start||'model origin')} close of ${money(s.sharePrice)}: approximately <b>${num(s.shares,0)} whole shares</b> costing ${money(s.shareCost)}, with ${money(s.shareRemainder)} of the stock allocation unspent.`}</p><p class="sizing-method">Range comes from maximizing expected CRRA utility of the simulated stock/cash wealth across feasible weights; γ is 4 / 2 / 1 for cautious / balanced / growth. The stress case reduces annual drift while preserving simulated dispersion. This is sensitivity to assumptions, not a validated personal recommendation.</p>`;
 updateLongTerm();
}
function updateLongTerm(){
 const el=$('#longTermResults'),input=$('#holdYears');if(!el||!input)return;
 if(!input.checkValidity()||input.value===''||!$('#investment').checkValidity()){el.textContent='Enter a whole number of years from 1 to 30 and a valid proposed investment.';return}
 const years=Number(input.value),amount=state.investment,projection=longTermProjection({amount,years,mu:params.mu,sigma:params.sigma});
 const inflation=$('#inflation'),rate=inflation&&inflation.checkValidity()?Number(inflation.value)/100:NaN,deflator=Number.isFinite(rate)?(1+rate)**years:NaN;
 el.innerHTML=`<div class="long-term-grid"><div><small>MEDIAN ENDING VALUE · NOMINAL</small><b>${money(projection.median)}</b></div><div><small>MIDDLE 80% · NOMINAL</small><b>${money(projection.low)}–${money(projection.high)}</b></div><div><small>MEDIAN IN START-DATE DOLLARS</small><b>${Number.isFinite(deflator)?money(projection.median/deflator):'Enter valid inflation'}</b></div></div><p class="notice">Constant μ, σ, and assumed inflation for ${years} ${years===1?'year':'years'}. Inflation is user-entered because future CPI is unknown. This excludes dividends, taxes, changing business conditions, and additional savings. It ignores the one-time event shock, is separate from the game score, and becomes less credible farther out.</p>`;
}
function lockForecast(){
 if(loading){toast('Wait for the price request to finish before locking your forecast.');return}
 if(!Number.isFinite(state.budget)||state.budget<=0||!Number.isFinite(state.allocation)||state.allocation<0||state.allocation>100||!Number.isFinite(state.maxLossPct)||state.maxLossPct<0||state.maxLossPct>100){toast('Enter a valid budget, loss limit, and allocation in the stock calculator.');return}
 if(state.mode==='replay'&&!context.hasActual){toast('Choose a company with enough real history before and after the replay origin.');return}
 const base=simulate({s0:context.startPrice,mu:baseline.mu,sigma:baseline.sigma,days:state.days});
 state.locked={id:globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),created:new Date().toISOString(),symbol:state.symbol,mode:state.mode,origin:context.start,requestedOrigin:state.date,days:state.days,weights:{...state.weights},allocation:state.allocation,shock:{...state.shock},startPrice:context.enough?context.startPrice:null,budget:state.budget,maxLossPct:state.maxLossPct,riskProfile:state.riskProfile,unitPrice:context.enough?(context.rows[context.index].rawClose??context.rows[context.index].close):null,mu:params.mu,sigma:params.sigma,baseline:{...baseline},median:model.median,lo:model.lo,hi:model.hi,terminal:model.terminal,baselineTerminal:base.terminal,source:visibleSourceLabel(context.data),sourceKind:context.data?.kind||'illustrative',sourceAsOf:context.data?.asOf||context.start,sourceAdjustment:context.data?.adjustment||'',sourceClose:context.enough?context.startPrice:null,seed:731};
 journal.unshift(state.locked);const persisted=save('quantlab-journal',journal);applyLocked();if(persisted)toast('Forecast locked and saved in this browser. Export the journal for a portable backup.');
}
function applyLocked(){document.querySelectorAll('[data-event],#company,#origin,#horizon,#shockProbability,#shockMove,#saveBull,#saveBear,#replay,#forward,#refresh').forEach(el=>el.disabled=true);$('#lock').disabled=true;$('#lock').textContent='Forecast locked ✓';$('#reveal').disabled=state.mode!=='replay'||!context.hasActual;$('#reset').textContent='New round ↺';$('#journalShortcut').classList.remove('hidden');$('#lockNotice').textContent=state.mode==='replay'?'Your forecast is frozen. Select Reveal actual outcome, then open the journal to compare runs.':'Saved locally. Open the forecast journal to review it; evaluate after enough later observations exist.';$('#journalCount').textContent=journal.length;}
function scoreForecast(f,actual,source){
 const priced=Number.isFinite(f.startPrice)&&f.startPrice>0,startPrice=priced?f.startPrice:100,adjusted=Boolean(source?.adjusted),y=realizedPath(actual,startPrice,adjusted).at(-1),score=crps(f.terminal,y),bscore=crps(f.baselineTerminal,y),w=f.allocation/100;
 return{actualIndex:y,actualReturn:y/startPrice-1,score,baselineScore:bscore,medianError:Math.abs(f.median-y),covered:y>=f.lo&&y<=f.hi,netReturn:w*(y/startPrice-1)-w*.001,dollarPnl:Number.isFinite(f.budget)?f.budget*(w*(y/startPrice-1)-w*.001):null,end:actual.at(-1).date,outcomeSource:source?.label||source?.source||f.source,outcomeAsOf:source?.asOf||actual.at(-1).date,attribution:factorChecks(f,y)};
}
function reveal(){
 if(!state.locked||!context.hasActual)return;
 state.revealed=true;
 const f=state.locked,result=scoreForecast(f,context.actual,context.data),priced=Number.isFinite(f.startPrice)&&f.startPrice>0,unit=priced?'share price':'index';
 f.result=result;save('quantlab-journal',journal);drawChart();
 $('#results').innerHTML=`<section class="panel"><div class="panel-body"><div class="eyebrow">THE REVEAL / ${result.end}</div><h3>A forecast meets reality.</h3><div class="result-row"><span>Actual ending ${unit}</span><b>${priced?money(result.actualIndex):num(result.actualIndex)} (${pct(result.actualReturn)})</b></div><div class="result-row"><span>Your median / absolute error</span><b>${priced?money(f.median):num(f.median)} / ${priced?money(result.medianError):num(result.medianError)+' points'}</b></div><div class="result-row"><span>Your CRPS / baseline CRPS ↓</span><b>${num(result.score,2)} / ${num(result.baselineScore,2)} ${priced?'dollars':'index points'}</b></div><div class="result-row"><span>Actual inside your 80% interval?</span><b>${result.covered?'Yes':'No'}</b></div><div class="result-row"><span>Allocation net return / stock-only net</span><b>${pct(result.netReturn)} / ${pct(result.actualReturn-.001)}</b></div>${Number.isFinite(result.dollarPnl)?`<div class="result-row"><span>Practice budget outcome</span><b>${result.dollarPnl>=0?'+':''}${money(result.dollarPnl)} on ${money(f.budget)}</b></div>`:''}<p class="small-text">${result.score<result.baselineScore?'Your assumptions improved the distribution score in this round.':result.score===result.baselineScore?'Your distribution matches the baseline.':'The unchanged baseline scored better in this round.'} Lower CRPS is better. One result does not establish a reliable forecasting edge.</p><div class="callout">The realized path shows <b>what happened</b>. It does not establish which event caused it. When Yahoo adjusted closes are available, the realized return includes vendor split and dividend adjustments and is rescaled to the origin share price. It is a return-equivalent value, not the actual later share quote. Otherwise the comparison uses raw closes and omits dividends.</div><button class="secondary" id="revealJournal" type="button">Open saved run and leaderboard ↗</button></div></section>`;
 $('#revealJournal').onclick=showJournal;
 $('#reveal').disabled=true;toast('Actual prices revealed. Open the journal to compare saved runs.');
}
async function refreshData(options={}){
 if(state.locked)return;
 if(!providerAvailable()){if(!options.auto)toast('Selected provider is not configured. Choose Yahoo Finance or import CSV.');return}
 const selected=priceProvider,symbol=state.symbol,origin=options.origin||null,old=providerStatus[selected];
 if(old.retryUntil>Date.now()){providerStatus[selected]={...old,symbol};if($('#feedStatus'))$('#feedStatus').innerHTML=statusMarkup();if(!options.auto)toast('Provider cooldown is active. Try again after '+new Date(old.retryUntil).toLocaleTimeString()+'.');return}
 if(imports[symbol]){if(!options.auto)toast('A local CSV overrides provider prices for this company.');return}
 const requestKey=[selected,symbol,origin||'recent',state.days].join(':');if(loading&&pendingPriceKey!==requestKey)autoRequested.delete(pendingPriceKey);pendingPriceKey=requestKey;autoRequested.set(requestKey,Date.now());const revision=++requestRevision;loading=true;paintLoading();if($('#testProvider'))$('#testProvider').disabled=true;
 try{
  const query=new URLSearchParams({symbol,provider:selected,days:String(state.days)});if(origin)query.set('origin',origin);
  const response=await priceLoader.load([selected,symbol,origin||'recent',state.days].join(':'),'/api/prices?'+query,{force:Boolean(options.force)});
  if(response.stale||revision!==requestRevision||state.symbol!==symbol||priceProvider!==selected)return;
  const d=response.data,data={...d,label:(d.providerName||providerNames[selected])+' daily · '+d.asOf,kind:'provider'};
  providerStatus[selected]={symbol,state:'loaded',message:symbol+' daily history received through '+d.asOf+'.'};
  if(state.locked)return;
  liveCache[selected+':'+symbol]=data;replayOriginFromData();loading=false;
  if(active==='game')game();else if(active==='calculator')calculator();else if(active==='data')dataPage();
  if(!options.auto)toast(replayIsHidden()?providerNames[selected]+' replay history loaded. Later prices remain hidden.':providerNames[selected]+' history loaded through '+d.asOf+'.');
 }catch(error){
  if(revision!==requestRevision||state.symbol!==symbol||priceProvider!==selected)return;
  providerStatus[selected]={symbol,state:'error',message:error.message,retryUntil:error.retryAfter?Date.now()+error.retryAfter*1000:0};
  loading=false;if(active==='game')game();else if(active==='calculator')calculator();else if(active==='data')dataPage();
  if(!options.auto)toast(error.message);
 }finally{
  if(revision===requestRevision){pendingPriceKey=null;loading=false;paintLoading();if($('#testProvider'))$('#testProvider').disabled=false;}
 }
}

function learning(){const c=company();view.innerHTML=heading('LEARNING LIBRARY','Understand the <em>business.</em>','A ticker is the beginning of the research, not the investment thesis.')+`<div class="content-grid two"><section class="card"><div class="research-company"><span class="ticker-icon">${c.symbol}</span><div><h3>${esc(c.name)}</h3><span class="pill">${c.sector}</span></div></div><p>${c.about}</p><h4>What to investigate</h4><p>${c.watch}</p><div class="buttons"><a class="secondary" href="https://www.sec.gov/edgar/search/#/q=${encodeURIComponent(c.name)}" target="_blank" rel="noopener">Read company filings ↗</a><button class="secondary" id="researchPlay">Model this company ↗</button></div><p class="notice">Business descriptions are general research context. “Established”, “growth-oriented”, and “specialist” are illustrative research cohorts, not current market-cap classifications or quality ratings.</p></section><section class="card"><div class="eyebrow">BEFORE YOU TOUCH A SLIDER</div><h3>Separate the story from the surprise.</h3><ul><li>What creates revenue and cash flow?</li><li>What is already reflected in the market price?</li><li>Which event affects demand, margins, financing, or risk premiums?</li><li>What would make your thesis wrong?</li><li>How much uncertainty remains after your research?</li></ul><a class="link" href="#math">Connect the economics to the mathematics ↗</a></section></div><div class="section-title"><h2>The company universe<span class="small-text"> / ${companies.length} businesses</span></h2></div><div class="filter-row"><input id="search" type="text" placeholder="Search name or ticker" aria-label="Search companies"><select id="sectorFilter" aria-label="Filter by sector"><option value="">All sectors</option>${[...new Set(companies.map(c=>c.sector))].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="panel table-wrap"><table class="watchlist"><thead><tr><th>COMPANY</th><th>SECTOR / PROFILE</th><th>KEY RESEARCH QUESTIONS</th><th></th></tr></thead><tbody id="companyRows"></tbody></table></div><div class="section-title"><h2>Build an evidence stack.</h2></div><div class="content-grid">${[['01','Primary filings','Read the 10-K, 10-Q, risk factors, debt notes, and management discussion. Record the publication date, not just the reporting period.','SEC EDGAR','https://www.sec.gov/edgar/search/'],['02','Macroeconomic releases','Track inflation, employment, growth, and rates. Historical releases can be revised; a modern series is not always the vintage available then.','ALFRED data vintages','https://alfred.stlouisfed.org/'],['03','Market expectations','Compare a thesis with valuation, analyst assumptions, and option-implied uncertainty. Popularity and familiarity do not imply attractiveness.','OCC options education','https://www.optionseducation.org/']].map(([n,t,p,l,u])=>`<div class="card"><div class="eyebrow">${n} / RESEARCH SOURCES</div><h3>${t}</h3><p>${p}</p><a class="link" href="${u}" target="_blank" rel="noopener">${l} ↗</a></div>`).join('')}</div>`;const rows=()=>{const q=$('#search').value.toLowerCase(),sector=$('#sectorFilter').value;const matched=companies.filter(c=>(!sector||c.sector===sector)&&(c.name+' '+c.symbol).toLowerCase().includes(q));$('#companyRows').innerHTML=matched.length?matched.map(c=>`<tr><td><b>${c.symbol}</b><small>${c.name}</small></td><td>${c.sector}<small>${c.profile}</small></td><td>${c.watch}</td><td><button data-pick="${c.symbol}">Explore ↗</button></td></tr>`).join(''):'<tr><td colspan="4">No companies match your search.</td></tr>';document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{cancelPriceLoad();state.symbol=b.dataset.pick;replayDateExplicit=false;newRound();learning();window.scrollTo(0,0)})};rows();$('#search').oninput=rows;$('#sectorFilter').onchange=rows;$('#researchPlay').onclick=()=>location.hash='game';}
async function market(){view.innerHTML=heading('MARKET CONTEXT','Read the <em>crosscurrents.</em>','Investigate exposures, expectations, and transmission channels before forming a view.')+`<div class="callout amber"><strong>This page is a research framework, not a current market outlook or ranked stock recommendation.</strong> No up-to-date macro assessment is inferred from archived prices. ${state.mode==='replay'?'Current news is withheld while historical replay is selected.':'Connected news, when available, is shown separately with source timestamps.'}</div><div class="section-title"><h2>The forces behind the numbers.</h2></div><div class="content-grid">${marketThemes.map(([t,s,p,l,u])=>`<section class="card"><div class="eyebrow">${t.toUpperCase()}</div><h3>${s}</h3><p>${p}</p><a class="link" href="${u}" target="_blank" rel="noopener">${l} ↗</a></section>`).join('')}</div><div class="section-title"><h2>Where to direct your research.</h2><span class="small-text">Examples are candidates for study, not endorsements.</span></div><div class="panel table-wrap"><table class="watchlist"><thead><tr><th>SECTOR</th><th>OPPORTUNITY QUESTIONS</th><th>WHAT COULD GO WRONG?</th><th>COMPANIES TO COMPARE</th></tr></thead><tbody>${sectors.map(([s,o,r,c])=>`<tr><td>${s}</td><td>${o}</td><td>${r}</td><td>${c}</td></tr>`).join('')}</tbody></table></div><div class="section-title"><h2>Source-linked news.</h2></div><section class="card" id="news"><p>${state.mode==='replay'?'Historical mode is active. Current headlines would leak future information. Switch to Forward lab to request current news.':config.newsConfigured?'Load provider headlines for the selected company. Headlines are evidence to investigate, not causal estimates.':'Connect a market-data provider in Data & connections to enable fetched headlines. Meanwhile, consult filings and dated primary releases above.'}</p>${state.mode==='forward'&&config.newsConfigured?'<button class="secondary" id="loadNews">Load headlines ↻</button>':''}</section>`;if($('#loadNews'))$('#loadNews').onclick=async()=>{let el=$('#loadNews');el.disabled=true;el.textContent='Loading…';try{let r=await fetch('/api/news?symbol='+state.symbol),d=await r.json();if(!r.ok)throw new Error(d.error);$('#news').innerHTML=d.articles.length?d.articles.map(a=>`<div class="feed-row"><small>${esc(a.source)} / ${esc(a.time)}</small><p><a href="${esc(a.url)}" target="_blank" rel="noopener">${esc(a.title)} ↗</a></p><p>${esc(a.summary)}</p></div>`).join(''):'No headlines were returned for this company.'}catch(e){$('#news').textContent=e.message}};}
function algorithm(){establish();view.innerHTML=heading('ALGORITHM & STRATEGY','A model you can <em>question.</em>','Follow the assumptions all the way from an economic story to a simulated decision.')+`<div class="content-grid two"><section class="card"><div class="eyebrow">SITE V2 / MODEL CONTRACT 0.2</div><h3>Transparent before sophisticated.</h3><p>Constant-coefficient geometric Brownian motion is our starting point. It gives exact positive-price transitions and a clear way to separate return assumptions from uncertainty. It does not discover mispricing or prove an event causes a return.</p><div class="formula">Company + dated prices<br>→ pre-origin calibration<br>→ grouped event adjustments<br>→ physical-measure simulation<br>→ forecast + constrained position sizing<br>→ held-out comparison</div><a class="link" href="#code">Inspect the implementation ↗</a></section><section class="card"><div class="eyebrow">INVESTMENT PHILOSOPHY</div><h3>Evidence earns conviction.</h3><ul><li>Judge distribution quality over many rounds.</li><li>Compare against an unchanged model and simple alternatives.</li><li>Compare modeled utility across stock/cash weights, then test a weaker drift assumption.</li><li>Keep the 5th-percentile loss within a practice budget limit.</li><li>Distinguish a good business from an attractive price.</li><li>Keep a dated thesis and an explicit falsification condition.</li></ul><div class="callout">A favorable simulated mean is a consequence of assumptions. It is not independent evidence of an investable edge.</div></section></div><details class="model-details"><summary>All slider coefficients and limits</summary><div class="section-title"><h2>What the controls actually do.</h2></div><div class="panel table-wrap"><table class="watchlist"><thead><tr><th>FACTOR</th><th>DRIFT COEFFICIENT a</th><th>LOG-VOL COEFFICIENT b</th><th>EXPOSURE MULTIPLIER</th></tr></thead><tbody>${params.effects.map(e=>`<tr><td>${e.name}<small>${e.group}</small></td><td>${pct(events.find(x=>x.id===e.id).drift)}</td><td>${events.find(x=>x.id===e.id).vol.toFixed(2)}</td><td>${e.exposure.toFixed(2)}× for ${company().symbol}</td></tr>`).join('')}</tbody></table></div><p class="notice">Illustrative coefficients; not event-study estimates. Within each group, signed contributions are averaged, then group means are summed. Energy-price drift reverses sign for Energy. μ is capped at −35% to +45%; σ at 5% to 120%. See Math for the complete equations.</p></details><details class="model-details"><summary>Position-sizing derivation</summary><div class="section-title"><h2>How the V2 sizing range works.</h2></div><section class="card"><p>For each feasible stock weight, V2 evaluates simulated end-of-horizon stock/cash wealth after an illustrative 10 bps round-trip cost. A 5th-percentile loss limit caps the weight; expected CRRA utility chooses a model-preferred weight. A second calculation lowers annual drift but preserves dispersion. The two weights form a sensitivity band, not a confidence interval.</p><div class="formula">Wᵢ(w) = B[1 + w(Rᵢ − 0.001)]<br>maximize meanᵢ Uγ(Wᵢ/B), 0 ≤ w ≤ wₘₐₓ<br>U₁(x)=log x; Uγ(x)=(x^(1−γ)−1)/(1−γ)<br>γ = 4 cautious, 2 balanced, 1 growth<br>B·w·(0.001 − R₅%) ≤ stated loss limit</div><p>The model uses the simulated 5th percentile, not a guaranteed worst-case bound. It does not know the investor’s other holdings or liabilities. Dated history simulations now start at the source share close; legacy journal runs remain on an index starting at 100. Share estimates use the source close.</p><a class="link" href="#code">Read the sizing code ↗</a></section></details><div class="section-title"><h2>How we test a strategy.</h2></div><div class="step-list">${[['Define the decision rule','Write the rule before evaluating outcomes. Specify horizon, information set, costs, and how positions change.'],['Separate development and evaluation','Use time-ordered train/validation/test periods and walk-forward evaluation. Account for survivorship, revised data, and multiple testing.'],['Measure more than returns','Study calibration, CRPS, turnover, drawdowns, tail losses, and performance relative to a benchmark.'],['Move into forward paper testing','Log forecasts before outcomes arrive. Paper execution cannot establish live fill quality or future profitability.']].map(([t,p])=>`<div><span><h4>${t}</h4><p>${p}</p></span></div>`).join('')}</div>`;}
function math(){view.innerHTML=heading('THE MATHEMATICS','Follow every <em>assumption.</em>','From information sets and Brownian motion to pricing, simulation, and forecast evaluation.')+`<div class="callout" style="margin-bottom:22px">Read in sequence or open any chapter. Every concept connects back to a parameter or decision in the game. The baseline is GBM. The game also has an optional one-time event jump; stochastic volatility and regime switching remain future extensions.</div>${mathTopics.map(([n,t,b],i)=>`<details class="math-topic" ${i===0?'open':''}><summary><span>${n}</span>${t}</summary><div class="body">${b}</div></details>`).join('')}<section class="math-topic"><div class="body"><h3>10 / Expected utility and position sizing</h3><p>Given budget B, stock weight w, simulated stock return Rᵢ, and cost c, the terminal portfolio wealth in path i is Wᵢ=B[1+w(Rᵢ−c)]. The game maximizes average CRRA utility over weights satisfying a modeled 5th-percentile loss limit. Log utility is the γ=1 case. A lower-drift stress run shows sensitivity to return estimation error.</p><div class="formula">w* = argmax₀≤w≤wₘₐₓ (1/N)Σᵢ Uγ(1+w(Rᵢ−c))<br>wₘₐₓ = min(1, L/[max(0,c−R₅%)])</div><p>L is the user’s maximum modeled 5th-percentile loss as a fraction of budget. If the simulated lower tail does not show a loss, this constraint alone leaves w capped at 1. The calculation is long-only, single-stock, cash at zero yield, and depends on an estimated distribution. It does not prove that the suggested weight will be safe or profitable.</p></div></section><details class="math-topic"><summary><span>11</span>Event jumps</summary><div class="body"><h3>One-time shocks</h3><p>With user-set probability p, one random session in a path multiplies the share price by 1 + J. Paths without the event follow GBM alone. The same Brownian seed keeps scenario comparisons stable.</p><div class="formula">S(t⁺) = S(t⁻)(1 + J),  event probability = p</div><p>J and p are illustrative assumptions. This is a finite-horizon scenario mixture, not a calibrated Poisson intensity or a prediction that an event will occur.</p></div></details><details class="math-topic"><summary><span>12</span>Portfolio dependence</summary><div class="body"><h3>Correlated paths</h3><p>The portfolio model aligns daily returns by date, estimates correlations, shrinks off-diagonal correlations toward zero, and uses a Cholesky factor to generate related Brownian shocks.</p><div class="formula">Z ~ N(0,I),  ε = LZ,  LLᵀ = C<br>Wₜ = B[cash weight + Σᵢ wᵢ Sᵢ(t)/Sᵢ(0)]<br>σ²ₚ = Σᵢ Σⱼ wᵢwⱼσᵢσⱼCᵢⱼ</div><p>Each holding is buy-and-hold. Correlations, drift, and volatility are estimated from past returns and may change.</p></div></details><div class="content-grid two"><div class="card"><h3>Useful next extensions</h3><p>Introduce parameter uncertainty before adding complexity. Then compare a calibrated jump model, stochastic volatility, and regime switching using held-out distribution scores. More parameters create more opportunities to overfit.</p></div><div class="card"><h3>Learn the derivations</h3><p>The separate Quant Finance learning chat in Jaiden Folder covers the rigorous curriculum and documented trading-firm philosophies. This website keeps the model’s assumptions and implementation inspectable.</p><a class="link" href="https://personal.ntu.edu.sg/nprivault/MA5182/martingale-pricing-hedging.pdf" target="_blank" rel="noopener">Stochastic finance lecture notes ↗</a></div></div>`;}
async function code(){view.innerHTML=heading('OPEN IMPLEMENTATION','Read the <em>source.</em>','Inspect, reproduce, and challenge the calculations behind the interface.')+`<div class="callout" style="margin-bottom:20px">The website runs the JavaScript implementation. New price-based rounds start at the dated share close; V1/V2 journal rounds retain their original index-100 basis. The dependency-free Python reference mirrors the original GBM engine. The new portfolio and event-shock code runs in JavaScript and is available in the tabs below. Download it and run <span class="mono">python3 quant_model.py</span>. Price data and third-party references retain their own rights; source visibility is not itself a copyright license.</div><div class="tab-row"><button class="active" data-file="quant_model.py">Python reference</button><button data-file="model.js">JavaScript engine + shocks</button><button data-file="portfolio-model.js">Portfolio model</button><button data-file="portfolio-page.js">Portfolio UI</button><button data-file="sizing.js">Position sizing</button><button data-file="catalog.js">Companies & coefficients</button></div><div class="code-toolbar"><span id="filename">quant_model.py</span><div class="buttons"><button class="secondary" id="copyCode" style="color:#d8e9bd;border-color:#61784c">Copy</button><a class="primary lime" id="downloadCode" href="/quant_model.py" download>Download ↓</a></div></div><pre class="code" id="sourceCode">Loading source…</pre><p class="notice">Site V2 / source files served from this deployment. Python and JavaScript match for baseline GBM. The portfolio and event-shock extensions are tested separately in JavaScript.</p>`;let source='';async function load(file){try{let r=await fetch('/'+file);if(!r.ok)throw new Error('Source unavailable');source=await r.text();$('#filename').textContent=file;$('#sourceCode').textContent=source;$('#downloadCode').href='/'+file;document.querySelectorAll('[data-file]').forEach(b=>b.classList.toggle('active',b.dataset.file===file))}catch(e){$('#sourceCode').textContent=e.message}}document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>load(b.dataset.file));$('#copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(source);toast('Source copied.')}catch{toast('Clipboard is unavailable. Use Download to save the source.')}};load('quant_model.py');}
function dataPage(){view.innerHTML=heading('DATA & CONNECTIONS','Know what feeds <em>your model.</em>','Source, timestamps, freshness, and limitations belong beside every forecast.')+`<div class="content-grid two"><section class="card"><div class="eyebrow">DAILY MARKET DATA</div><h3>Yahoo Finance connection</h3><label class="field">PRICE PROVIDER<select id="priceProvider"><option value="yahoo" ${priceProvider==='yahoo'?'selected':''}>Yahoo Finance · no key</option><option value="alpha" ${priceProvider==='alpha'?'selected':''}>Alpha Vantage · server key</option></select></label><div class="callout ${providerStatus[priceProvider].state==='error'?'amber':''}" style="margin-top:16px">${statusMarkup()}</div><p>Daily history loads automatically when you open the game or select a company. No manual load step is needed. Yahoo needs no account or API key for this public interface. In Forward lab, successful requests display the last session; historical replay masks later prices until reveal.</p><div class="buttons"><button class="secondary" id="testProvider" ${loading?'disabled':''}>Load ${providerNames[priceProvider]} prices for ${state.symbol} ↗</button><a class="secondary" href="#game">Open simulation ↗</a></div><p class="small-text">Successful responses are cached for up to 15 minutes. Unlocked Forward lab checks every 15 minutes while open. Requests respect rate-limit cooldowns; no login cookies, authentication workarounds, or automatic retries are used.</p><p class="notice">Yahoo’s chart interface is unofficial and can change or deny server access. Availability is verified only after prices load. Adjusted closes are used when returned; incomplete current-session bars are excluded. This is daily history, not guaranteed real-time quotes.</p>${replayIsHidden()?'<p class="small-text">The full Yahoo history link appears after the replay outcome is revealed.</p>':`<a class="link" href="https://finance.yahoo.com/quote/${state.symbol}/history/" target="_blank" rel="noopener">View Yahoo history ↗</a>`}<details style="margin-top:18px"><summary>Optional Alpha Vantage & news</summary><p class="small-text">Alpha Vantage is ${config.providers?.alpha?.available?'configured':'not configured'}. It remains an alternative price and news provider. Yahoo news uses an unofficial recent-headline feed and may be rate-limited. Configure the server secret <span class="mono">ALPHA_VANTAGE_API_KEY</span> through Site runtime settings to enable it. Yahoo prices do not require this key. This site does not read this chat or automatically browse Google.</p></details></section><section class="card"><div class="eyebrow">BRING YOUR OWN HISTORY</div><h3>Import a daily price CSV</h3><p>Choose a company, then import a CSV with <span class="mono">Date,Close</span> columns. Dates must be YYYY-MM-DD and prices positive. Provide at least 41 observations for calibration; replay needs additional observations after the origin.</p><label class="field">ASSIGN DATA TO<select id="importSymbol">${choices()}</select></label><input class="file-input" id="csvFile" type="file" accept=".csv,text/csv" aria-label="Import daily price CSV"><button class="secondary" id="importBtn">Import into this browser ↗</button><div id="importStatus" class="small-text" role="status" style="margin-top:12px"></div><p class="notice">CSV contents stay in your browser and are not uploaded. Imported data overrides the archive/provider for that ticker until removed. Verify adjustments, currency, trading calendar, and the absence of missing or erroneous observations.</p><button class="quiet" id="clearImport">Remove imported data for selected company</button></section><section class="card"><div class="eyebrow">INCLUDED / REAL HISTORICAL OBSERVATIONS</div><h3>An archive you can replay today.</h3><p>AAPL, MSFT, IBM, and SBUX have bundled daily observations from 2013 through March 1, 2016. The archive is deliberately fixed; it is not current market data. The company universe spans ${companies.length} businesses, but the other companies need an import/provider connection for real-data replay.</p><p class="small-text">With real history, the price chart starts at the dated share close; without it, the display uses an illustrative index of 100. Return calibration uses the source return series, while dollar price comparisons use source closes. The archive’s corporate-action methodology is not verified. It supports educational return comparisons, not a clean point-in-time production backtest. Selection and survivorship biases remain.</p><a class="link" href="https://github.com/plotly/datasets/blob/master/stockdata.csv" target="_blank" rel="noopener">Inspect the original public dataset ↗</a></section><section class="card"><div class="eyebrow">YOUR RESEARCH RECORD</div><h3>Local forecasts. Portable evidence.</h3><p>The forecast journal stores origins, weights, parameter estimates, distributions, allocations, and scores in this browser. It is not account-synced and may disappear if browser storage is cleared. Download records you want to keep.</p><div class="buttons"><button class="secondary" id="exportJournal">Export journal JSON ↓</button><a class="secondary" href="/sample-prices.csv" download>Example CSV ↓</a></div><p class="notice">No broker connection or live order route is present. A future personal-finance layer would need cash flows, assets, liabilities, taxes, and goal modeling; this release focuses on the agreed stock simulation game.</p></section></div>`;$('#importBtn').onclick=async()=>{const file=$('#csvFile').files[0];if(!file){$('#importStatus').textContent='Choose a CSV file first.';return}if(file.size>3e6){$('#importStatus').textContent='Use a file smaller than 3 MB.';return}try{const rows=parseCSV(await file.text()),symbol=$('#importSymbol').value;imports[symbol]={rows,label:'Local CSV · '+file.name,kind:'import',imported:new Date().toISOString()};save('quantlab-imports',imports);$('#importStatus').textContent=`Imported ${rows.length} observations, ${rows[0].date} to ${rows.at(-1).date}.`;cancelPriceLoad();state.symbol=symbol;newRound();toast('CSV imported. Open the simulation game to use it.')}catch(e){$('#importStatus').textContent=e.message}};$('#clearImport').onclick=()=>{delete imports[$('#importSymbol').value];save('quantlab-imports',imports);$('#importStatus').textContent='Imported data removed for this company. Archive/provider data is available again.'};$('#exportJournal').onclick=()=>downloadJSON(journal,'quantlab-journal.json');$('#priceProvider').onchange=e=>{if(state.locked){toast('Start a new simulation round before changing providers.');e.target.value=priceProvider;return}cancelPriceLoad();priceProvider=e.target.value;autoRequested.clear();save('quantlab-price-provider',priceProvider);dataPage()};$('#testProvider').onclick=()=>refreshData({force:true});}
function downloadJSON(data,name){let url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let journalFilter='all';
function factorNarrative(f){
 const a=f.result?.attribution||[];
 if(!a.length)return 'No individual slider sensitivity was recorded for this run.';
 const best=[...a].sort((x,y)=>y.scoreChange-x.scoreChange)[0];
 const effect=best.scoreChange>0?`improved this run’s CRPS by ${num(best.scoreChange,2)} points versus leaving it at 50%`:`did not improve this run’s CRPS versus leaving it at 50%`;
 return `${esc(best.name)} at ${num(best.weight,0)}% ${effect}. This is a one-factor model comparison against the realized close, not proof that the event moved the stock.`;
}
function validForecast(f){
 return f&&typeof f==='object'&&typeof f.id==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(f.id)&&companies.some(c=>c.symbol===f.symbol)&&['forward','replay'].includes(f.mode)&&Number.isInteger(f.days)&&f.days>0&&f.days<=252&&typeof f.created==='string'&&Number.isFinite(Date.parse(f.created))&&f.weights&&typeof f.weights==='object'&&events.every(e=>Number.isFinite(f.weights[e.id])&&f.weights[e.id]>=0&&f.weights[e.id]<=100)&&f.baseline&&Number.isFinite(f.baseline.mu)&&Number.isFinite(f.baseline.sigma)&&Number.isFinite(f.mu)&&Number.isFinite(f.sigma)&&Number.isFinite(f.median)&&Number.isFinite(f.lo)&&Number.isFinite(f.hi)&&Number.isFinite(f.allocation)&&f.allocation>=0&&f.allocation<=100&&(f.startPrice===undefined||f.startPrice===null||(Number.isFinite(f.startPrice)&&f.startPrice>0))&&(f.budget===undefined||(Number.isFinite(f.budget)&&f.budget>0&&f.budget<=1e8))&&(f.maxLossPct===undefined||(Number.isFinite(f.maxLossPct)&&f.maxLossPct>=0&&f.maxLossPct<=100))&&(f.riskProfile===undefined||['cautious','balanced','growth'].includes(f.riskProfile))&&(f.shock===undefined||(Number.isFinite(f.shock?.probability)&&f.shock.probability>=0&&f.shock.probability<=1&&Number.isFinite(f.shock?.move)&&f.shock.move>-1&&f.shock.move<=1))&&Array.isArray(f.terminal)&&Array.isArray(f.baselineTerminal)&&f.terminal.length>=2&&f.terminal.length<=5000&&f.baselineTerminal.length>=2&&f.baselineTerminal.length<=5000&&[...f.terminal,...f.baselineTerminal].every(x=>Number.isFinite(x)&&x>0);
}
function restoredForecast(f){
 const r={id:f.id,created:f.created,symbol:f.symbol,mode:f.mode,origin:typeof f.origin==='string'?f.origin:null,requestedOrigin:typeof f.requestedOrigin==='string'?f.requestedOrigin:null,days:f.days,weights:Object.fromEntries(events.map(e=>[e.id,f.weights[e.id]])),allocation:f.allocation,shock:f.shock?{probability:f.shock.probability,move:f.shock.move}:null,startPrice:Number.isFinite(f.startPrice)&&f.startPrice>0?f.startPrice:null,budget:Number.isFinite(f.budget)?f.budget:null,maxLossPct:Number.isFinite(f.maxLossPct)?f.maxLossPct:null,riskProfile:['cautious','balanced','growth'].includes(f.riskProfile)?f.riskProfile:null,unitPrice:Number.isFinite(f.unitPrice)&&f.unitPrice>0?f.unitPrice:null,mu:f.mu,sigma:f.sigma,baseline:{mu:f.baseline.mu,sigma:f.baseline.sigma,observations:f.baseline.observations||0},median:f.median,lo:f.lo,hi:f.hi,terminal:f.terminal,baselineTerminal:f.baselineTerminal,source:String(f.source||'Imported forecast').slice(0,300),sourceKind:String(f.sourceKind||'import').slice(0,40),sourceAsOf:String(f.sourceAsOf||'').slice(0,30),sourceAdjustment:String(f.sourceAdjustment||'').slice(0,300),sourceClose:Number.isFinite(f.sourceClose)?f.sourceClose:null,seed:Number.isInteger(f.seed)?f.seed:731};
 const y=f.result?.actualIndex;
 if(Number.isFinite(y)&&y>0&&typeof f.result.end==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(f.result.end)){
  const w=r.allocation/100,startPrice=r.startPrice??100;
  r.result={actualIndex:y,actualReturn:y/startPrice-1,score:crps(r.terminal,y),baselineScore:crps(r.baselineTerminal,y),medianError:Math.abs(r.median-y),covered:y>=r.lo&&y<=r.hi,netReturn:w*(y/startPrice-1)-w*.001,dollarPnl:Number.isFinite(f.budget)?f.budget*(w*(y/startPrice-1)-w*.001):null,end:f.result.end,outcomeSource:String(f.result.outcomeSource||r.source).slice(0,300),outcomeAsOf:String(f.result.outcomeAsOf||f.result.end).slice(0,30),attribution:factorChecks(r,y)};
 }
 return r;
}
function showJournal(){
 const evaluated=journal.filter(f=>f.result),coverage=evaluated.length?evaluated.filter(f=>f.result.covered).length/evaluated.length:null;
 const symbols=[...new Set(journal.map(f=>f.symbol))].sort();if(journalFilter!=='all'&&!symbols.includes(journalFilter))journalFilter='all';
 const ranked=rankedForecasts(journal,journalFilter),summary=stockSummaries(journal),visible=journal.filter(f=>journalFilter==='all'||f.symbol===journalFilter);
 const board=ranked.length?`<div class="table-wrap"><table class="watchlist leaderboard"><thead><tr><th>RANK</th><th>STOCK / RUN</th><th>CRPS SKILL ↑</th><th>CRPS ↓</th><th>PRICE SOURCE</th></tr></thead><tbody>${ranked.map((row,i)=>{const f=row.forecast;return `<tr><td><b>#${i+1}</b></td><td><b>${esc(f.symbol)}</b><small>${esc(f.origin||'Unknown origin')} → ${esc(f.result.end)} · ${f.days} sessions</small></td><td class="${row.skill>=0?'positive':'negative'}">${pct(row.skill)}</td><td>${num(f.result.score,2)}<small>Baseline ${num(f.result.baselineScore,2)}</small></td><td>${esc(f.result.outcomeSource||f.source)}<small>as of ${esc(f.result.outcomeAsOf||f.result.end)}</small></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No evaluated predictions for this selection yet. Lock a historical replay, reveal its outcome, or evaluate a forward forecast when later prices are available.</div>';
 const stocks=summary.length?`<div class="table-wrap"><table class="watchlist"><thead><tr><th>STOCK</th><th>EVALUATED RUNS</th><th>AVERAGE CRPS SKILL ↑</th><th>BEST RUN</th></tr></thead><tbody>${summary.map(s=>`<tr><td><b>${esc(s.symbol)}</b></td><td>${s.runs}</td><td class="${s.meanSkill>=0?'positive':'negative'}">${pct(s.meanSkill)}</td><td>${pct(s.bestSkill)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="small-text">Stock summaries appear after evaluation.</div>';
 $('#journalContent').innerHTML=`<div class="eyebrow">FORECAST JOURNAL / LEADERBOARD</div><h2>Which assumptions predicted best?</h2><p class="small-text">${journal.length} saved predictions · ${evaluated.length} evaluated ${coverage===null?'':'· 80% interval coverage: '+pct(coverage,0)}. Lower CRPS is better within a run. Older runs use index points; new price-based runs use dollars. Skill compares each run to its own baseline and is the cross-run ranking measure.</p><div class="journal-tools"><label class="field">SHOW STOCK<select id="journalFilter"><option value="all">All stocks</option>${symbols.map(symbol=>`<option value="${esc(symbol)}" ${journalFilter===symbol?'selected':''}>${esc(symbol)}</option>`).join('')}</select></label><button class="secondary" id="exportAll">Export journal JSON ↓</button><label class="secondary import-label" for="importJournal">Import journal JSON ↑</label><input id="importJournal" type="file" accept="application/json,.json" aria-label="Import journal JSON"></div><div class="callout">A normal reload keeps records in this browser. Export a backup to preserve them if browser data is cleared or you switch devices. Import merges that backup with records already here. Rankings use only evaluated forecasts; repeated runs on the same outcome are not independent evidence.</div><h3 class="journal-heading">Prediction leaderboard</h3>${board}<h3 class="journal-heading">By stock</h3>${stocks}<h3 class="journal-heading">Saved runs</h3>${visible.length?visible.map(f=>`<div class="journal-entry"><div><b>${esc(f.symbol)}</b> <span class="pill">${f.mode==='replay'?'REPLAY':'FORWARD'}</span> <span class="small-text">${esc(f.origin||'Illustrative origin')} · ${f.days} sessions</span></div><p>μ ${pct(f.mu)} / σ ${pct(f.sigma)} · median ${num(f.median)} · allocation ${num(f.allocation,0)}%${Number.isFinite(f.budget)?' of $'+num(f.budget,0)+' budget':''}<br>Forecast source: ${esc(f.source)} · locked ${esc(f.created.slice(0,19).replace('T',' '))} UTC</p>${f.result?`<p>Actual ${f.startPrice?money(f.result.actualIndex):num(f.result.actualIndex)} · CRPS ${num(f.result.score,2)} / baseline ${num(f.result.baselineScore,2)} ${f.startPrice?'USD':'index points'} · net return ${pct(f.result.netReturn)}${Number.isFinite(f.result.dollarPnl)?' · practice P/L $'+num(f.result.dollarPnl,2):''}</p><p class="factor-note">${factorNarrative(f)}</p>`:`<p>Awaiting evaluation. Use the same price series with ${f.days} later sessions.</p><button class="secondary" data-eval="${esc(f.id)}">Evaluate against available data</button>`}<button class="quiet" data-export="${esc(f.id)}">Download record ↓</button></div>`).join(''):'<div class="empty">No saved predictions for this selection.</div>'}`;
 $('#journalFilter').onchange=e=>{journalFilter=e.target.value;showJournal()};
 $('#exportAll').onclick=()=>downloadJSON(journal,'quantlab-journal.json');
 $('#importJournal').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>10e6){toast('Choose a journal backup smaller than 10 MB.');return}try{const parsed=JSON.parse(await file.text());if(!Array.isArray(parsed)||parsed.length>250||!parsed.every(validForecast))throw new Error('This is not a valid Quant Lab journal backup.');const restored=parsed.map(restoredForecast),merged=new Map([...restored,...journal].map(f=>[f.id,f]));journal=[...merged.values()].sort((a,b)=>b.created.localeCompare(a.created));if(save('quantlab-journal',journal)){toast('Journal restored. Predictions and rankings are available.');$('#journalCount').textContent=journal.length;showJournal()}}catch(error){toast(error.message||'Could not read the journal backup.')}};
 document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>downloadJSON(journal.find(f=>f.id===b.dataset.export),'quantlab-forecast.json'));
 document.querySelectorAll('[data-eval]').forEach(b=>b.onclick=()=>{const f=journal.find(f=>f.id===b.dataset.eval),data=sourceFor(f.symbol),rows=data?.rows||[],idx=rows.findIndex(r=>r.date===f.origin);if(idx<0||rows.length<idx+f.days+1){toast('Not enough matching observations yet. Refresh or import more history.');return}if(!Number.isFinite(f.sourceClose)||Math.abs((f.startPrice?(rows[idx].rawClose??rows[idx].close):rows[idx].close)/f.sourceClose-1)>.001){toast('The origin price differs from the locked source. Use the same series and adjustment basis.');return}f.result=scoreForecast(f,rows.slice(idx,idx+f.days+1),data);if(save('quantlab-journal',journal))showJournal()});
 if(!$('#journal').open)$('#journal').showModal();
}
$('#historyBtn').onclick=showJournal;$('#journal .close').onclick=()=>$('#journal').close();
function home(){
 view.innerHTML=`<div class="home-hero"><div class="eyebrow">QUANT LAB / INTERACTIVE RESEARCH</div><h1>Build a forecast.<br><em>Test your thinking.</em></h1><p>Choose a stock, change the assumptions, and see a distribution of possible prices. Then compare your view with a baseline or combine stocks in a portfolio.</p><div class="buttons"><a class="primary lime" href="#game">Open the game</a><a class="secondary" href="#portfolio">Build a portfolio</a></div></div><section class="home-section" id="tutorial"><div class="eyebrow">START HERE</div><h2>Three ways to play</h2><div class="tab-row tutorial-tabs"><button data-tutorial="historical" class="active">Historical</button><button data-tutorial="future">Future</button><button data-tutorial="portfolio">Portfolio · advanced</button></div><div id="tutorialBody" class="tutorial-body"></div></section><section class="home-section"><div class="eyebrow">THE MODEL</div><h2>How assumptions become paths</h2><div class="home-steps"><div><b>Observe</b><p>Dated prices estimate a starting drift and volatility. Historical replay uses only prices before the chosen start date.</p></div><div><b>Adjust</b><p>Each market slider changes an illustrative company exposure to drift or volatility. An event shock adds a possible one-time price jump.</p></div><div><b>Simulate</b><p>Brownian shocks produce many paths: dS = μS dt + σS dW. The chart shows their median and middle 80%.</p></div><div><b>Check</b><p>Lock a forecast before revealing history, compare it with the unchanged baseline, and inspect the source code.</p></div></div><div class="buttons"><a class="secondary" href="#algorithm">Read the algorithm</a><a class="secondary" href="#code">Read the code</a></div></section>`;
 const lessons={historical:['Historical replay','Pick an earlier date. Set the sliders and optional shock without seeing later prices. Lock your view, reveal the actual outcome, then inspect your score in the journal.','#game'],future:['Forward forecast','Start from the latest completed daily close. Make a forecast for a chosen horizon and return later when prices arrive.','#game'],portfolio:['Portfolio mode','Choose two to five stocks and weights. The model estimates how their daily returns move together and compares that result with separately modeled stocks.','#portfolio']};
 const show=name=>{const [title,body,link]=lessons[name];$('#tutorialBody').innerHTML=`<h3>${title}</h3><p>${body}</p><a class="primary lime" href="${link}">Try this mode</a>`;document.querySelectorAll('[data-tutorial]').forEach(button=>button.classList.toggle('active',button.dataset.tutorial===name))};document.querySelectorAll('[data-tutorial]').forEach(button=>button.onclick=()=>show(button.dataset.tutorial));show('historical');
}
function portfolio(){portfolioPage(view,{sourceFor,archiveFor:symbol=>archive?.series[symbol]?{rows:archive.series[symbol],label:"Plotly archive · 2013–2016",kind:"archive"}:null,scenarioWeights:()=>state.weights,providerAvailable})}
function calculator(){
 establish();view.innerHTML=heading('STOCK CALCULATOR','Put a number on <em>your view.</em>','The calculations below use the stock, horizon, sliders, and event shock currently selected in the game.')+`<div class="callout calculator-context"><strong>${esc(state.symbol)} · ${state.days} sessions · ${context.enough?money(context.startPrice):'index 100'} starting price</strong><span>μ ${pct(params.mu)} · σ ${pct(params.sigma)} · shock ${pct(state.shock.probability,0)} chance / ${pct(state.shock.move,0)} move</span><a href="#game">Change game assumptions</a></div><section class="decision" id="decision"><h3>What if you invested this amount?</h3><div class="decision-grid sizing-inputs"><label class="field">PROPOSED STOCK INVESTMENT / $ ${tip('A hypothetical purchase amount; this is not an order.')}<input id="investment" type="number" min="0" max="100000000" step="0.01" value="${state.investment}"></label><label class="field">PRACTICE BUDGET / $ ${tip('Stock plus cash for this exercise. The proposed purchase divided by the budget is your stock allocation.')}<input id="budget" type="number" min="1" max="100000000" step="0.01" value="${state.budget}"></label><label class="field">DOWNSIDE BUDGET / % ${tip('Limits the modeled 5th-percentile loss as a share of your practice budget. Worse losses remain possible.')}<input id="maxLossPct" type="number" min="0" max="100" step="0.5" value="${state.maxLossPct}"></label><label class="field">RISK POSTURE ${tip('Sets γ in the expected-utility sizing equation: cautious 4, balanced 2, growth 1.')}<select id="riskProfile"><option value="cautious" ${state.riskProfile==='cautious'?'selected':''}>Cautious</option><option value="balanced" ${state.riskProfile==='balanced'?'selected':''}>Balanced</option><option value="growth" ${state.riskProfile==='growth'?'selected':''}>Growth</option></select></label><label class="field">STOCK ALLOCATION / %<input id="allocation" type="number" min="0" max="100" step="any" value="${state.allocation}"></label></div><div id="decisionSummary" class="sizing-summary"></div><div id="sizingResults"></div><button id="useSizing" class="secondary">Try model midpoint</button><details class="model-details"><summary>How sizing works</summary><p>Weights maximize expected CRRA utility across simulated stock-and-cash outcomes, subject to a modeled downside limit. The band compares the base drift with a lower-drift stress case. It is a sensitivity comparison, not a safe-investment recommendation.</p></details></section><section class="panel long-term" id="longTermPanel"><div class="panel-body"><h3>What if you held it longer?</h3><div class="decision-grid"><label class="field">YEARS TO HOLD ${tip('A separate constant-parameter extrapolation. It does not change or score the game forecast.')}<input id="holdYears" type="number" min="1" max="30" step="1" value="${state.holdYears}"></label><label class="field">ASSUMED INFLATION / % YEARLY ${tip('Your assumption for future inflation, not a Yahoo forecast. Real-dollar values divide nominal values by (1 + inflation)^years.')}<input id="inflation" type="number" min="-5" max="30" step="0.1" value="${state.inflation}"></label></div><div id="longTermResults"></div></div></section><section class="panel options-panel"><div class="panel-body"><h3>Hypothetical option price</h3><p>Black–Scholes prices a European option using this scenario’s volatility. It excludes the game’s event shock and is not a live option-chain quote.</p><div class="settings-grid"><label class="field">STRIKE / $<input id="strike" type="number" min="1" max="100000" value="${context.startPrice.toFixed(2)}"></label><label class="field">MATURITY / CALENDAR DAYS<input id="maturity" type="number" min="1" max="3650" value="30"></label><label class="field">RISK-FREE RATE / %<input id="rate" type="number" min="-5" max="30" value="4"></label><label class="field">DIVIDEND YIELD / %<input id="yield" type="number" min="0" max="30" value="0"></label></div><div id="bsResults" class="metric-grid"></div><details class="model-details"><summary>Why this differs from the stock forecast</summary><p>Black–Scholes uses a risk-neutral pricing measure. Changing the physical expected return μ does not change this option price when the other inputs stay fixed. Scenario volatility is not market-implied volatility.</p></details></div></section>`;
 for(const id of ['allocation','investment','budget','maxLossPct','riskProfile'])$('#'+id).oninput=e=>{const value=id==='riskProfile'?e.target.value:Number(e.target.value);if(id==='riskProfile'||Number.isFinite(value))state[id]=value;if(id==='investment'&&Number.isFinite(value)&&value>=0){if(value>state.budget){state.budget=value;$('#budget').value=value}state.allocation=state.budget?value/state.budget*100:0;$('#allocation').value=Number(state.allocation.toFixed(4))}else if(id==='budget'&&Number.isFinite(value)&&value>0){state.investment=Math.min(state.investment,value);state.allocation=state.investment/value*100;$('#investment').value=state.investment;$('#allocation').value=Number(state.allocation.toFixed(4))}else if(id==='allocation'&&Number.isFinite(value)){state.investment=state.budget*value/100;$('#investment').value=Number(state.investment.toFixed(2))}decisionSummary();saveDraft()};
 $('#useSizing').onclick=()=>{if(!$('#budget').checkValidity()||!$('#maxLossPct').checkValidity())return;const result=positionSizing();state.allocation=Math.round((result.range[0]+result.range[1])*50);state.investment=state.budget*state.allocation/100;$('#allocation').value=state.allocation;$('#investment').value=Number(state.investment.toFixed(2));decisionSummary();saveDraft()};
 $('#holdYears').oninput=e=>{const years=Number(e.target.value);if(Number.isInteger(years))state.holdYears=years;updateLongTerm();saveDraft()};$('#inflation').oninput=e=>{const value=Number(e.target.value);if(Number.isFinite(value))state.inflation=value;updateLongTerm();saveDraft()};
 const optionCalc=()=>{const els=['strike','maturity','rate','yield'].map(id=>$('#'+id));if(els.some(el=>!el.checkValidity()||el.value==='')){$('#bsResults').textContent='Enter valid option inputs.';return}const [strike,days,rate,yieldRate]=els.map(el=>Number(el.value));const result=blackScholes(context.startPrice,strike,days/365,rate/100,yieldRate/100,params.sigma);$('#bsResults').innerHTML=[['CALL',result.call],['PUT',result.put],['CALL DELTA',result.delta],['VEGA / 1 VOL POINT',result.vega]].map(([label,value])=>`<div class="metric"><small>${label}</small><b>${num(value,2)}</b></div>`).join('')};['strike','maturity','rate','yield'].forEach(id=>$('#'+id).oninput=optionCalc);decisionSummary();optionCalc();queueMicrotask(ensurePrices);
}
function research(){
 const c=company(),url=`https://finance.yahoo.com/quote/${encodeURIComponent(c.symbol)}/news/`;
 view.innerHTML=heading('RESEARCH LIBRARY','Read before you <em>model.</em>','Start with the company, examine its filings, and check dated headlines before changing a slider.')+`<section class="card"><div class="research-company"><span class="ticker-icon">${c.symbol}</span><div><h3>${esc(c.name)}</h3><span class="pill">${esc(c.sector)}</span></div></div><label class="field">COMPANY<select id="researchCompany">${choices()}</select></label><p>${esc(c.about)}</p><p><strong>Investigate:</strong> ${esc(c.watch)}</p><div class="buttons"><a class="secondary" href="#game">Model this stock</a><a class="secondary" href="https://www.sec.gov/edgar/search/#/q=${encodeURIComponent(c.name)}" target="_blank" rel="noopener">Search SEC filings</a></div></section><section class="card"><h3>What to look for in SEC filings</h3><div class="home-steps"><div><b>10-K</b><p>Annual business, risks, and audited statements. Start with business, risk factors, and management discussion.</p></div><div><b>10-Q</b><p>Quarterly revenue, margins, cash flow, and balance sheet changes.</p></div><div><b>8-K</b><p>Material announcements such as leadership changes, earnings releases, and major agreements.</p></div></div><p class="small-text">Search the company name or ticker, filter to the form type, and record the filing date. In a historical replay, read only filings available before your chosen origin.</p></section><section class="card"><div class="panel-head"><h3>Recent Yahoo Finance headlines</h3><a class="secondary" href="${url}" target="_blank" rel="noopener">Open Yahoo news</a></div><div id="researchNews" class="news-list">${state.mode==='replay'?'Current headlines are hidden during historical replay to avoid leaking later information. Switch to Forward lab to see them.':'Loading dated headlines…'}</div></section><details class="model-details research-market"><summary>Market context and sector questions</summary><div class="content-grid">${marketThemes.map(([name,title,body,label,link])=>`<div class="card"><h3>${esc(title)}</h3><p>${esc(body)}</p><a href="${esc(link)}" target="_blank" rel="noopener">${esc(label)}</a></div>`).join('')}</div><div class="table-wrap"><table class="watchlist"><thead><tr><th>SECTOR</th><th>RESEARCH QUESTION</th><th>RISK</th><th>EXAMPLES</th></tr></thead><tbody>${sectors.map(([sector,opportunity,risk,names])=>`<tr><td>${esc(sector)}</td><td>${esc(opportunity)}</td><td>${esc(risk)}</td><td>${esc(names)}</td></tr>`).join('')}</tbody></table></div></details>`;
 $('#researchCompany').onchange=e=>{state.symbol=e.target.value;newRound();research()};
 if(state.mode==='replay')return;
 fetch('/api/news?'+new URLSearchParams({symbol:c.symbol,provider:'yahoo'})).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||'News unavailable.');return data}).then(data=>{if(!$('#researchNews')||state.symbol!==c.symbol)return;$('#researchNews').innerHTML=data.articles.length?data.articles.map(article=>`<div class="feed-row"><small>${esc(article.source)} · ${esc(article.time?new Date(article.time).toLocaleString():'Date unavailable')}</small><p><a href="${esc(article.url)}" target="_blank" rel="noopener">${esc(article.title)}</a></p></div>`).join(''):'No current headlines returned. Use the Yahoo news link above.'}).catch(error=>{if($('#researchNews'))$('#researchNews').textContent=`${error.message} Use the Yahoo news link above. The feed is unofficial and does not provide a reliable historical archive.`});
}
const viewNames={home:'Start',game:'Simulation game',portfolio:'Portfolio',calculator:'Stock calculator',learning:'Research & market',algorithm:'Algorithm',math:'Mathematics',code:'Source code',data:'Data & connections'};
function route(){active=location.hash.slice(1)||'home';if(active==='market')active='learning';if(!viewNames[active])active='home';document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===active));$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${viewNames[active]}`;$('#journalCount').textContent=journal.length;({home,game,portfolio,calculator,learning:research,algorithm,math,code,data:dataPage})[active]();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);
async function boot(){view.innerHTML='<div class="loading">Opening your research desk…</div>';try{const r=await fetch('/data/history.json');if(!r.ok)throw new Error('Historical archive unavailable.');archive=await r.json();try{config=await(await fetch('/api/config')).json()}catch{}if(!providerAvailable()&&config.providers?.yahoo?.available){priceProvider='yahoo';save('quantlab-price-provider',priceProvider);}$('#connectionDot').textContent='○';route();setInterval(()=>{if(['game','calculator'].includes(active)&&state.mode==='forward'&&!state.locked&&providerAvailable())refreshData({auto:true})},15*60*1000)}catch(e){view.innerHTML=`<div class="callout amber">${esc(e.message)} Please reload to try again.</div>`}}
boot();
